import {isOriginalHero} from './original-heroes.js';
import { hasJobMechanic, onAscensionBasic, onAscensionSkill, onAscensionLanding, onAscensionReaction } from './ascension-combat.js';
import { getCombatStats, getSkillGeometry } from './combat-stats.js';
const TAU=Math.PI*2;
const alive=e=>e&&!e.dead&&e.hp>0&&!(e.spawnDelay>0);
const d2=(a,b)=>(a.x-b.x)**2+(a.y-b.y)**2;
const job=g=>g.heroJob||g.player.job;
export function resetJobMechanics(g){g.jobMechanics={swords:0,momentum:0,resourceTime:0,pending:[],blinkHits:0,serials:new Set(),reactionSerials:new Set(),whirlwind:null,guardCounter:false,bladeMark:null};return g.jobMechanics;}
const state=g=>g.jobMechanics||resetJobMechanics(g);
const enemies=(g,at,r,cap=5)=>g.enemies.filter(alive).filter(e=>d2(e,at)<=(r+(e.radius||0))**2).sort((a,b)=>d2(a,at)-d2(b,at)||a.id-b.id).slice(0,cap);
function fx(g,spec){(g.heroEffects||=[]).push({...spec,life:spec.life||.25,maxLife:spec.life||.25});}
function hit(api,e,n,category='basicSecondary'){if(alive(e))api.damage(e,n,'#d5ffff',category);}
function circle(g,at,r,n,api,category='basicSecondary',cap=5){r*=getCombatStats(g).area;for(const e of enemies(g,at,r,cap))hit(api,e,n,category);fx(g,{shape:'circle',visualKind:hasJobMechanic(g,'summoner_master')?'pactBurst':'commanderSlash',x:at.x,y:at.y,radius:r,angle:0,width:TAU});}
function line(g,at,angle,n,api,category='basicSecondary',length=220,cap=5){const dx=Math.cos(angle),dy=Math.sin(angle),width=18*getCombatStats(g).area;const list=g.enemies.filter(alive).map(e=>({e,t:(e.x-at.x)*dx+(e.y-at.y)*dy,h:Math.abs((e.x-at.x)*dy-(e.y-at.y)*dx)})).filter(o=>o.t>=0&&o.t<=length&&o.h<=width+(o.e.radius||0)).sort((a,b)=>a.t-b.t||a.e.id-b.e.id).slice(0,cap);for(const o of list)hit(api,o.e,n,category);fx(g,{shape:'line',visualKind:'jobBladeLine',x:at.x,y:at.y,toX:at.x+dx*length,toY:at.y+dy*length,angle,radius:width,width,life:.3});}
function later(g,delay,fn,targetId=null){state(g).pending.push({delay,fn,targetId});}
function command(g,target,api){if(!alive(target))return;const s=getCombatStats(g);const troops=(g.companions||[]).filter(c=>c.hp>0).sort((a,b)=>a.id-b.id);let ordinary=0,elite=0;for(const c of troops){if(c.elite?elite++>=1:ordinary++>=3)continue;c.focusTargetId=target.id;const reach=(c.radius||19)+(target.radius||20)+(c.elite?55:8);if(d2(c,target)<=reach**2){hit(api,target,c.damage*s.damage,'companion');c.anim='attack';c.animTime=0;}else c.jobCommand={targetId:target.id,remaining:1.5};}}
export function onJobBasicAttack(g,info,api){if(isOriginalHero(g))return;const s=state(g),{target,damage,angle=0,third,shotSerial=0,rank=1,branch,forcedCommand=false}=info;if(s.serials.has(shotSerial))return;s.serials.add(shotSerial);if(s.serials.size>64)s.serials.delete(s.serials.values().next().value);onAscensionBasic(g,info,api);
 // Signature weapons now own the travelling waves and their evolution geometry.
 // Keep the job's sword resource and placed-blade response without a duplicate wave.
 if(hasJobMechanic(g,'blade_master')&&third){s.swords=Math.min(3,s.swords+1);s.resourceTime=8;if(!info.signatureWeapon){if(rank===4&&branch==='a')circle(g,g.player,150,damage*.75,api);else{line(g,g.player,angle,damage*(rank>=2?.55:.35),api,'basicSecondary',rank>=2?220:160,rank>=2?5:3);if(rank===4&&branch==='b')later(g,.16,()=>hit(api,target,damage*.35),target.id);}}if(s.bladeMark){line(g,s.bladeMark,Math.atan2(target.y-s.bladeMark.y,target.x-s.bladeMark.x),damage*.35,api);s.bladeMark=null;}}
 if(hasJobMechanic(g,'swift_blade')){s.momentum=Math.min(3,s.momentum+1);s.resourceTime=Math.max(s.resourceTime,5);if(third)line(g,g.player,angle+Math.PI,damage*.35,api,undefined,112);}
 if(hasJobMechanic(g,'summoner_master')&&(third||forcedCommand)&&(forcedCommand||!(s.commandUntil>(g.time||0)))){command(g,target,api);s.commandUntil=(g.time||0)+1;}
 if(hasJobMechanic(g,'blink_master')&&shotSerial%2===0){const a=(g.heroState.blinkAnchors||[]).filter(a=>a.remaining>0&&d2(a,target)<=96**2).sort((a,b)=>d2(a,target)-d2(b,target)||a.id-b.id)[0];if(a)a.charge=Math.min(2,(a.charge||0)+1);}
}
export function onJobBasicHit(g,{target,damage,element,shotSerial},api){if(isOriginalHero(g))return;const s=state(g);if(hasJobMechanic(g,'blade_master')){const field=g.fields.find(f=>f.type==='sword'&&f.life>0&&f.suspended>0&&!(f.jobCooldown>0)&&d2(f,target)<=f.radius**2);if(field){field.suspended--;field.jobCooldown=.6;hit(api,target,damage*.5);fx(g,{shape:'ring',visualKind:'bladeImpact',x:target.x,y:target.y,radius:30});}}
 if(!hasJobMechanic(g,'mage_master'))return;const m=target.jobElements||={};const now=g.time||0;if(!s.reactionSerials.has(shotSerial)&&!(m.cooldown>now)&&((element==='fire'&&m.frost>now)||(element==='frost'&&m.fire>now)||(element==='stone'&&(m.fire>now||m.frost>now))||m.rock>now)){s.reactionSerials.add(shotSerial);if(s.reactionSerials.size>64)s.reactionSerials.delete(s.reactionSerials.values().next().value);m.cooldown=now+1;m.rock=0;onAscensionReaction(g,target,element,damage);hit(api,target,damage*.4,'reaction');fx(g,{shape:'circle',visualKind:element==='stone'?'stoneSplash':'elementImpact',element,x:target.x,y:target.y,radius:40});if(element==='fire'&&g.heroState.frostAura&&d2(g.heroState.frostAura,target)<=g.heroState.frostAura.radius**2)for(const e of enemies(g,target,55*getCombatStats(g).area,3))if(e!==target)hit(api,e,damage*.2,'reaction');}m[element]=now+3;
}
export function onJobSkill(g,id,api){if(isOriginalHero(g))return;onAscensionSkill(g,id);const s=state(g),p=g.player,m=getCombatStats(g).damage,angle=g._jobCastAngle||0;
 if(hasJobMechanic(g,'blade_master')){if(id==='guard')s.guardCounter=true;if(id==='swordField'){const f=g.fields.at(-1);f.suspended=s.swords;s.swords=0;}if(['cleave','bladeWave'].includes(id)&&s.swords){s.swords--;const at={x:p.x,y:p.y},wave=id==='bladeWave'?g.projectiles.at(-1):null;later(g,id==='cleave'?.18:1.05,()=>line(g,wave?{x:wave.x,y:wave.y}:at,id==='bladeWave'?angle+Math.PI:angle,36*m,api,'active'));}}
 if(hasJobMechanic(g,'swift_blade')){if(['dash','quickCut'].includes(id)){s.whirlwind=null;s.dashMomentum=s.momentum>0;s.momentum=Math.max(0,s.momentum-1);}if(id==='guard'&&g.heroKit){g.heroKit.forceThirdTime=5;}if(id==='cleave'){const count=s.momentum;s.momentum=0;for(let i=0;i<count;i++)later(g,.12*(i+1),()=>circle(g,p,80,20*m,api,'active'));}if(id==='whirlwind'){s.whirlwind={life:2,elapsed:0,tick:0,momentum:s.momentum,damage:23*m,radius:getSkillGeometry(g,id).radius/getCombatStats(g).area};s.momentum=0;}}
 if(hasJobMechanic(g,'summoner_master')){if(id==='recallSummons'){if(g.heroKit){g.heroKit.focusId=null;g.heroKit.focusTime=0;}}if(id==='summonGuard'&&s.fullSummons){const target=g.enemies.find(e=>e.id===g.heroKit?.focusId&&alive(e));for(const c of g.companions.filter(c=>!c.elite&&c.hp>0).slice(0,3)){if(target){const dist=Math.hypot(target.x-c.x,target.y-c.y),move=Math.min(180,Math.max(0,dist-c.radius-target.radius-8));const x=c.x+(dist?(target.x-c.x)/dist*move:0),y=c.y+(dist?(target.y-c.y)/dist*move:0);if(!api.movementHitsWall?.(c.x,c.y,x,y,c.radius)){c.x=x;c.y=y;}}}if(target)command(g,target,api);}if(id==='summonElite'){const c=g.companions.find(c=>c.elite&&c.hp>0);if(c)circle(g,c,105,c.damage*m,api,'companion',5);}}
}
export function onJobDashComplete(g,api){if(isOriginalHero(g))return;const s=state(g);if(hasJobMechanic(g,'blade_master'))s.bladeMark={x:g.player.x,y:g.player.y,remaining:2};if(hasJobMechanic(g,'swift_blade')){if(s.dashMomentum)circle(g,g.player,80,24*getCombatStats(g).damage,api,'active');s.dashMomentum=false;if(g.heroKit)g.heroKit.forceThirdTime=5;}}
export function onJobGuardHit(g,api){if(isOriginalHero(g))return;const s=state(g);if(hasJobMechanic(g,'blade_master')&&s.guardCounter&&g.player.guardTime>0){s.guardCounter=false;s.swords=Math.min(3,s.swords+1);s.resourceTime=8;circle(g,g.player,90,25*getCombatStats(g).damage,api,'active');}}
export function updateJobMechanics(g,dt,api){if(isOriginalHero(g))return;if(g.phase!=='playing'||g.player.hp<=0)return;const s=state(g);s.resourceTime=Math.max(0,s.resourceTime-dt);if(!s.resourceTime){s.momentum=0;if(s.swords){s.swords--;s.resourceTime=1;}}if(s.bladeMark&&(s.bladeMark.remaining-=dt)<=0)s.bladeMark=null;for(const f of g.fields)f.jobCooldown=Math.max(0,(f.jobCooldown||0)-dt);const pending=s.pending;s.pending=[];for(const q of pending){q.delay-=dt;if(q.targetId!=null&&!g.enemies.some(e=>e.id===q.targetId&&alive(e)))continue;if(q.delay<=0)q.fn();else s.pending.push(q);}
 const w=s.whirlwind;if(w){w.elapsed+=dt;w.life=Math.max(0,2-w.elapsed);while(w.tick<4&&w.elapsed>=w.tick*.5){circle(g,g.player,w.radius,w.damage,api,'active',8);if(w.tick<w.momentum)circle(g,g.player,w.radius+35,w.damage*.35,api,'active',5);w.tick++;}if(w.elapsed+1e-9>=2)s.whirlwind=null;}
 for(const c of g.companions||[]){const order=c.jobCommand;if(!order||c.hp<=0)continue;order.remaining-=dt;const target=g.enemies.find(e=>e.id===order.targetId&&alive(e));if(!target||order.remaining<=0){c.jobCommand=null;continue;}const reach=c.radius+target.radius+(c.elite?55:8);if(d2(c,target)<=reach**2){hit(api,target,c.damage*getCombatStats(g).damage,'companion');c.jobCommand=null;}}
}
export function onJobBlinkLanding(g,anchor,travel,api){if(isOriginalHero(g))return;onAscensionLanding(g,anchor,travel);if(!hasJobMechanic(g,'blink_master')||travel.chargedIds.has(anchor.id))return;travel.chargedIds.add(anchor.id);const charge=travel.charges.get(anchor.id)||0;const live=g.heroState.blinkAnchors.find(a=>a.id===anchor.id);if(live)live.charge=0;for(let i=0;i<charge;i++){const candidates=enemies(g,anchor,96,2),target=candidates[i%candidates.length];if(target)later(g,.1,()=>{const count=travel.chargeHits.get(target.id)||0;if(count<4){travel.chargeHits.set(target.id,count+1);hit(api,target,travel.damage*.35,'active');fx(g,{shape:'ring',visualKind:'bladeImpact',x:target.x,y:target.y,radius:25});}},target.id);}}
export function onJobBladeLanded(g,shot){if(isOriginalHero(g))return;if(!hasJobMechanic(g,'blink_master'))return;const target=enemies(g,shot,96,1)[0];if(target)later(g,.05,()=>{hit(g._jobApi,target,shot.damage*.35,'active');fx(g,{shape:'line',visualKind:'jobBladeLine',x:shot.x,y:shot.y,toX:target.x,toY:target.y,angle:Math.atan2(target.y-shot.y,target.x-shot.x),radius:8,width:8});},target.id);}

